            if(Busy)return;var result=outcomes.Get(Mode);if(result==null||result.Files.Length==0)return;string folder,name=null;var paths=result.Files;
            if(paths.Length==1){using(var d=new SaveFileDialog{Title="下载到…（同名自动编号）",FileName=Path.GetFileName(paths[0]),Filter="处理结果|*"+Path.GetExtension(paths[0]),OverwritePrompt=false,InitialDirectory=settings.OutputFolder}){if(d.ShowDialog(this)!=DialogResult.OK)return;folder=Path.GetDirectoryName(d.FileName);name=Path.GetFileNameWithoutExtension(d.FileName);}}else using(var d=new FolderBrowserDialog{Description="选择批量视频结果保存位置",SelectedPath=settings.OutputFolder}){if(d.ShowDialog(this)!=DialogResult.OK)return;folder=d.SelectedPath;}
            Queue(async token=>{await StopFrames();bool reporting=true;progress.Indeterminate=true;status.Text="正在准备下载…";var reporter=new Progress<DownloadUpdate>(p=>{if(!reporting||IsDisposed)return;progress.Indeterminate=p.Phase==SavePhase.Flushing;progress.Value=p.Percent;status.Text=p.Percent+"% · "+DownloadJob.SizeText(p.Written)+" / "+DownloadJob.SizeText(p.Total)+" · "+DownloadJob.SizeText(p.BytesPerSecond)+"/s";});try{await Task.Run(()=>DownloadJob.Save(paths,folder,name,token,p=>((IProgress<DownloadUpdate>)reporter).Report(p)));result.Downloaded=true;progress.Value=100;status.Text="已保存到 "+folder;settings.OutputFolder=folder;try{settings.Save();}catch(IOException){}catch(UnauthorizedAccessException){}}finally{reporting=false;}},"save");
        }
        public async Task StopAsync(){if(cancel!=null)cancel.Cancel();await operation;await StopFrames();}
        protected override void Dispose(bool disposing){if(disposing){poll.Dispose();seekTimer.Dispose();ClearPicture();outcomes.Dispose();try{Directory.Delete(previewFolder,true);}catch(IOException){}catch(UnauthorizedAccessException){}}base.Dispose(disposing);}
    }
}
